            ns[name.strip()] = eval(rhs.strip(), g, ns)
        return ns

    base = {"rho": 0.0, "a": 0.0, "beta": 0.0, "tau": 1.0, "eps": 1e-7}

    # 1) d(x,x) must vanish: same tangent vector for u and q
