def _mob(X, y, c, s):
    xn = X[0]*X[0] + X[1]*X[1]
    yn = y[0]*y[0] + y[1]*y[1]
    xy = X[0]*y[0] + X[1]*y[1]
    a = 1.0 + 2.0*c*s*xy + c*yn
    b = 1.0 - c*xn
    den = 1.0 + 2.0*c*s*xy + c*c*xn*yn + 1e-300
    return ((a*X[0] + b*y[0])/den, (a*X[1] + b*y[1])/den)

